<template>
  <div class="page-shell"><div class="page-heading"><div><h1>通知公告</h1><p>发布社区信息、安全提醒和政策咨询。</p></div><el-button v-if="['ADMIN','POLICE'].includes(auth.role)" type="primary" @click="open()"><el-icon><Plus/></el-icon>新建公告</el-button></div><section class="panel"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="搜索公告标题或内容" style="width:270px"/><el-select v-model="query.type" clearable placeholder="公告类型" style="width:140px"><el-option v-for="(v,k) in types" :key="k" :label="v" :value="k"/></el-select><el-select v-model="query.status" clearable placeholder="发布状态" style="width:140px"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-button @click="load"><el-icon><Search/></el-icon>查询</el-button></div><div class="table-wrap"><el-table :data="page.records" v-loading="loading"><el-table-column label="公告标题" min-width="260"><template #default="s"><div class="notice-title"><span :class="s.row.type"></span><div><b>{{s.row.title}}</b><small>{{types[s.row.type]}} · {{s.row.publisherName}}</small></div><el-tag v-if="s.row.pinned" size="small" type="warning">置顶</el-tag></div></template></el-table-column><el-table-column prop="content" label="内容摘要" min-width="260" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="statusType[s.row.status]">{{statuses[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="publishedAt" label="发布时间" width="170"/><el-table-column label="操作" width="190"><template #default="s"><el-button link @click="current=s.row;detailDialog=true">查看</el-button><template v-if="['ADMIN','POLICE'].includes(auth.role)"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button v-if="s.row.status!=='PUBLISHED'" link type="success" @click="publish(s.row.id)">发布</el-button><el-button v-else link type="warning" @click="withdraw(s.row.id)">撤回</el-button></template></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.pageNum" :total="page.total" layout="total,prev,pager,next" @current-change="load"/></div></div></section>
    <el-dialog v-model="dialog" :title="editing?'编辑公告':'新建公告'" width="650px"><el-form ref="formRef" :model="form" :rules="rules" label-width="85px"><el-form-item label="公告标题" prop="title"><el-input v-model="form.title"/></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="公告类型"><el-select v-model="form.type" style="width:100%"><el-option v-for="(v,k) in types" :key="k" :label="v" :value="k"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="是否置顶"><el-switch v-model="form.pinned" :active-value="1" :inactive-value="0"/></el-form-item></el-col></el-row><el-form-item label="公告内容" prop="content"><el-input v-model="form.content" type="textarea" :rows="8"/></el-form-item><el-form-item label="保存状态"><el-radio-group v-model="form.status"><el-radio value="DRAFT">保存草稿</el-radio><el-radio value="PUBLISHED">直接发布</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存公告</el-button></template></el-dialog><el-dialog v-model="detailDialog" :title="current.title" width="650px"><div class="article">{{current.content}}</div></el-dialog>
  </div>
</template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import http from'../api/http';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),types={GENERAL:'社区信息',SAFETY:'安全提醒',POLICY:'政策咨询'},statuses={DRAFT:'草稿',PUBLISHED:'已发布',WITHDRAWN:'已撤回'},statusType={DRAFT:'info',PUBLISHED:'success',WITHDRAWN:'warning'},query=reactive({pageNum:1,pageSize:10,keyword:'',type:'',status:''}),page=reactive({records:[],total:0}),loading=ref(false),dialog=ref(false),detailDialog=ref(false),editing=ref(null),current=ref({}),formRef=ref(),blank=()=>({title:'',content:'',type:'GENERAL',status:'DRAFT',pinned:0}),form=reactive(blank()),rules={title:[{required:true,message:'请输入标题'}],content:[{required:true,message:'请输入内容'}]};onMounted(load);async function load(){loading.value=true;try{Object.assign(page,await http.get('/notices',{params:query}))}finally{loading.value=false}}function open(row){editing.value=row?.id||null;Object.assign(form,blank(),row||{});dialog.value=true}async function save(){await formRef.value.validate();editing.value?await http.put(`/notices/${editing.value}`,form):await http.post('/notices',form);ElMessage.success('公告已保存');dialog.value=false;load()}async function publish(id){await http.put(`/notices/${id}/publish`);ElMessage.success('公告已发布');load()}async function withdraw(id){await http.put(`/notices/${id}/withdraw`);ElMessage.success('公告已撤回');load()}
</script><style scoped>.notice-title{display:flex;align-items:center;gap:10px}.notice-title>span{width:6px;height:30px;border-radius:3px;background:#8ba2ad}.notice-title>span.SAFETY{background:#e6a23c}.notice-title>span.POLICY{background:#0e8a7a}.notice-title div{flex:1}.notice-title b,.notice-title small{display:block}.notice-title small{font-size:10px;color:#92a4ad;margin-top:5px}.article{line-height:2;color:#456273;white-space:pre-wrap}</style>
